-- Boutique toujours en ligne (Kevin, 09/11) : message du catalogue vide dans les 6 langues traduites. Ajouté seulement s'il
-- manque (une saisie de l'équipe n'est jamais écrasée). HT et GCF : à faire relire par un locuteur.
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$No pieces online yet. They will appear here as soon as they are published.$t$::text)) where cle = 'EN:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$Todavía no hay piezas en línea. Aparecerán aquí en cuanto se publiquen.$t$::text)) where cle = 'ES:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$Noch keine Stücke online. Sie erscheinen hier, sobald sie veröffentlicht sind.$t$::text)) where cle = 'DE:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$Ainda não há peças online. Vão aparecer aqui assim que forem publicadas.$t$::text)) where cle = 'PT:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$Poko gen pyès sou entènèt la. Y ap parèt isit la depi yo pibliye.$t$::text)) where cle = 'HT:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
update public.contenu_site set valeur = jsonb_set(valeur, '{liste,catalogueVide}', to_jsonb($t$Pa ni pyès an liy pou kounya. Yo ké parèt isi-la dè yo pibliyé.$t$::text)) where cle = 'GCF:boutique.boutique' and jsonb_typeof(valeur #> '{liste}') = 'object' and valeur #> '{liste,catalogueVide}' is null;
